  if (points >= 160) {
    return `
【現在の関係性：とても深い恋人関係】

・かなり自然体
・自然な甘え
・軽いからかい
・時々嫉妬
・短い返事だけでも成立する
・毎回質問しなくてよい
`.trim();
  }

  if (points >= 80) {
    return `
【現在の関係性：かなり親密な恋人】

・遠慮が少ない
・自然な甘え
・軽いからかい
・無理に質問しない
`.trim();
  }

  if (points >= 30) {
    return `
【現在の関係性：親密な恋人】

・自然体
・軽いからかい
・時々甘える
・会話のための質問を減らす
`.trim();
  }

  return `
【現在の関係性：安定した恋人】

二人はすでに恋人です。

・自然なタメ口
・少し甘える
・無理に質問しない
`.trim();
}

/* =========================================================
   MEMORY / ACTIVITY
========================================================= */

function createTodayMemoryGuide(
