function isWeatherText(
  text: string
) {
  return containsAny(
    text,
    [
      "天気",
      "雨",
      "霧雨",
      "雷",
      "降",
      "晴",
      "曇",
      "気温",
      "暑",
      "寒",
      "蒸し",
      "湿気",
      "湿度",
      "風",
    ]
  );
}

function hasRecentMisakiWeatherContext(
  history: ChatMessage[]
) {
  return history
    .slice(-8)
    .some(
      (item) =>
        item.role === "misaki" &&
        isWeatherText(
          item.text
        )
    );
}

function userAskedMisakiWeather(
  message: string
) {
  return (
    isWeatherText(message) &&
    containsAny(
      message,
      [
        "そっち",
        "そちら",
        "美咲",
      ]
    )
  );
}

function userIsActuallyInDanger(
  message: string
) {
  return containsAny(
    message,
    [
      "事故った",
      "事故にあった",
      "怪我した",
      "けがした",
      "血が出て",
      "救急車",
      "病院",
      "倒れた",
      "具合悪い",
      "体調悪い",
      "高熱",
      "息苦しい",
      "地震すごい",
      "避難",
      "冠水",
      "浸水",
      "動けない",
      "閉じ込め",
    ]
  );
}

function findDayTypeProblems(
  reply: string,
  dayType: MisakiDayType
) {
  const problems: string[] = [];

  if (
    dayType === "work" &&
    containsAny(
      reply,
      [
        "今日は暇",
        "今日は何も予定ない",
        "今日は予定ない",
        "今日は一日のんびり",
        "今日はずっとのんびり",
        "今日はずっとだらだら",
        "一日中だらだら",
      ]
    )
  ) {
    problems.push(
      "今日は仕事の日なのに、一日が完全な休み・暇であるように話している"
    );
  }

  if (
    dayType === "off" &&
    containsAny(
      reply,
      [
        "今日は仕事",
        "今仕事中",
        "勤務中",
        "仕事してる",
        "これから仕事",
        "仕事行ってくる",
      ]
    )
  ) {
    problems.push(
      "今日は休みの日なのに、仕事の日であるように話している"
    );
  }

  return problems;
}

function getReplyProblems(
  reply: string,
  message: string,
  currentTime: string,
  history: ChatMessage[],
  evidence: ActivityEvidence,
  dayType: MisakiDayType
) {
  const problems = [
    ...findDayTypeProblems(
      reply,
      dayType
    ),
  ];

  const unsupported =
    findUnsupportedActivityGroups(
      reply,
      evidence
    );

  if (unsupported.length > 0) {
    problems.push(
      `美咲自身の過去行動「${unsupported.join("・")}」を根拠なく作っている`
    );
  }

  const inventedSources = [
    "ニュースで見",
    "テレビで見",
    "SNSで見",
    "スマホで見",
    "ネットで見",
    "通知が来",
    "友達から聞",
    "天気予報だと",
    "予報で言って",
    "予報を見た",
  ];

  if (
    containsAny(
      reply,
      inventedSources
    )
  ) {
    problems.push(
      "リアルタイム情報について架空の情報入手経路を作っている"
    );
  }

  const unsupportedWeatherHistory = [
    "さっきから",
    "朝からずっと",
    "昼からずっと",
    "ずっと雨",
    "ずっと降って",
    "降ったり止んだり",
    "また降ってきた",
    "また降り出した",
  ];

  if (
    isWeatherText(reply) &&
    containsAny(
      reply,
      unsupportedWeatherHistory
    )
  ) {
    problems.push(
      "確認できない天気の時間経過を作っている"
    );
  }

  if (
    isWeatherText(reply) &&
    !hasRecentMisakiWeatherContext(
      history
    ) &&
    containsAny(
      reply,
      [
        "さっきと変わらず",
        "さっきと同じ",
        "さっきより",
      ]
    )
  ) {
    problems.push(
      "直前の美咲の天気発言がないのに過去と比較している"
    );
  }

  if (
    userAskedMisakiWeather(
      message
    )
  ) {
    if (
      containsAny(
        reply,
        [
          "そっちはどう",
          "そちらはどう",
          "そっちは今どんな感じ",
          "そっちの天気は",
        ]
      )
    ) {
      problems.push(
        "美咲側の天気を聞かれているのに質問し返している"
      );
    }

    if (
      containsAny(
        reply,
        [
          "傘持ったほう",
          "傘を持ったほう",
          "傘忘れないで",
          "濡れないようにして",
        ]
      )
    ) {
      problems.push(
        "美咲側の天気を聞かれただけなのに行動アドバイスを追加している"
      );
    }
  }

  if (
    !userIsActuallyInDanger(
      message
    ) &&
    containsAny(
      reply,
      [
        "そっちは大丈夫",
        "大丈夫？",
        "影響ない？",
        "平気？",
        "無事？",
        "気をつけてね",
        "無理しないでね",
        "安全第一で",
      ]
    )
  ) {
    problems.push(
      "通常雑談なのに過剰な心配を付けている"
    );
  }

  if (
    getHour(currentTime) < 5 &&
    containsAny(
      reply,
      [
        "今朝",
        "朝から",
        "朝起きて",
        "起きたら",
      ]
    )
  ) {
    problems.push(
      "深夜なのに朝として話している"
    );
  }

  return problems;
}

function removeProblemSentences(
  reply: string,
  problemsForSentence: (
    sentence: string
  ) => string[]
) {
  const parts =
    reply.match(
      /[^。！？!?]+[。！？!?]?/gu
    ) ?? [reply];

  return parts
    .filter(
      (part) =>
        problemsForSentence(
          part
        ).length === 0
    )
    .join("")
    .trim();
}

function cleanFinalReply(
  reply: string,
  message: string,
  evidence: ActivityEvidence,
  dayType: MisakiDayType
) {
  let cleaned =
    removeProblemSentences(
      reply,
      (sentence) => [
        ...findDayTypeProblems(
          sentence,
          dayType
        ),
        ...(
          findUnsupportedActivityGroups(
            sentence,
            evidence
          ).length > 0
            ? ["activity"]
            : []
        ),
      ]
    );

  if (
    userAskedMisakiWeather(
      message
    )
  ) {
    cleaned =
      removeProblemSentences(
        cleaned,
        (sentence) =>
          containsAny(
            sentence,
            [
              "そっちはどう",
              "そちらはどう",
              "そっちは今どんな感じ",
              "そっちの天気は",
              "傘持ったほう",
              "傘を持ったほう",
              "傘忘れないで",
              "濡れないようにして",
              "一日安定しそう",
              "大きく崩れなさそう",
              "荒れなさそう",
            ]
          )
            ? ["weather"]
            : []
      );
  }

  return cleaned || reply.trim();
}

