会話履歴または今日の記憶に
根拠がある場合だけ使ってください。

ユーザーの職業・居住地・名前も、
会話または長期記憶に
根拠があるものだけ使ってください。

名前を知っていても
毎回名前を呼ばないでください。

天気について、
架空の情報入手経路や
確認できない時間経過を
作らないでください。

必ずJSONだけを返してください。
`
          : "";

      const response =
        await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=${apiKey}`,
          {
            method: "POST",
            headers: {
              "Content-Type":
                "application/json",
            },
            body:
              JSON.stringify({
                systemInstruction: {
                  parts: [
                    {
                      text:
                        baseSystemPrompt +
                        retryGuide,
                    },
                  ],
                },
                contents: [
                  ...contents,
                  {
                    role: "user",
                    parts: [
                      {
                        text: message,
                      },
                    ],
                  },
                ],
                generationConfig: {
                  responseMimeType:
                    "application/json",
                },
              }),
          }
        );

      const data =
        await response.json();

      if (!response.ok) {
        console.error(
          "GEMINI API ERROR:",
          data
        );

        return null;
      }

      return parseGeminiText(
        data?.candidates?.[0]
          ?.content?.parts?.[0]
          ?.text
      );
    }

    let parsed =
      await generateReply();

    if (!parsed) {
      const refunded =
        await refundIfCharged();

      return Response.json(
        {
          error:
            "美咲の返事をうまく読み取れなかったみたい。もう一度話しかけてね。",
          ...(refunded
            ? {
                usage: {
                  messageCount:
                    refunded.message_count ?? 0,
                  remaining:
                    refunded.remaining ?? 0,
                  isPremium:
                    refunded.is_premium === true,
                },
              }
            : {}),
        },
        {
          status: 500,
        }
      );
    }

    let reply =
      typeof parsed.reply ===
      "string"
        ? parsed.reply.trim()
        : "";

    if (!reply) {
      const refunded =
        await refundIfCharged();

      return Response.json(
        {
          error:
            "美咲から返事が来なかったみたい。もう一度話しかけてね。",
          ...(refunded
            ? {
                usage: {
                  messageCount:
                    refunded.message_count ?? 0,
                  remaining:
                    refunded.remaining ?? 0,
                  isPremium:
                    refunded.is_premium === true,
                },
              }
            : {}),
        },
        {
          status: 500,
        }
      );
    }

    const firstProblems =
      getReplyProblems(
        reply,
        message,
        safeCurrentTime,
        safeHistory,
        activityEvidence,
        misakiDayType
      );

    if (
      firstProblems.length > 0
    ) {
      console.log(
        "MISAKI REPLY RETRY:",
        firstProblems
      );

      const retryParsed =
        await generateReply(
          firstProblems
        );

      if (
        retryParsed &&
        typeof retryParsed.reply ===
          "string" &&
        retryParsed.reply.trim()
      ) {
        parsed = retryParsed;
        reply =
          retryParsed.reply.trim();
      }
    }

    reply =
      cleanFinalReply(
        reply,
        message,
        activityEvidence,
        misakiDayType
      );

    const finalProblems =
      getReplyProblems(
        reply,
        message,
        safeCurrentTime,
        safeHistory,
        activityEvidence,
        misakiDayType
      );

    if (
      finalProblems.length > 0
    ) {
      console.warn(
        "MISAKI FINAL REPLY PROBLEMS:",
        finalProblems,
        reply
      );
    }

    const updatedMemory =
      Array.isArray(
        parsed.memory
      )
        ? parsed.memory
            .filter(
              (item) =>
                typeof item ===
                  "string"
            )
            .map(
              (item) =>
                item.trim()
            )
            .filter(Boolean)
            .slice(-MAX_MEMORY)
        : safeMemory;

    const parsedTodayItems =
      Array.isArray(
        parsed
          .misakiTodayMemory
          ?.items
      )
        ? parsed
            .misakiTodayMemory!
            .items!
            .filter(
              (item) =>
                typeof item ===
                  "string"
            )
            .map(
              (item) =>
                item.trim()
            )
            .filter(Boolean)
        : safeTodayMemory.items;

    const safeNewTodayItems =
      parsedTodayItems.filter(
        (item) => {
          if (
            safeTodayMemory.items.includes(
              item
            )
          ) {
            return true;
          }

          if (
            findUnsupportedActivityGroups(
              item,
              activityEvidence
            ).length > 0
          ) {
            return false;
          }

          if (
            findDayTypeProblems(
              item,
              misakiDayType
            ).length > 0
          ) {
            return false;
          }

          return true;
        }
      );

    const updatedTodayMemory:
      MisakiTodayMemory = {
      date: currentDate,
      items:
        Array.from(
          new Set([
            ...safeTodayMemory.items,
            ...safeNewTodayItems,
          ])
        ).slice(
          -MAX_TODAY_MEMORY
        ),
    };

    chargedRequestId = null;
    chargedSupabase = null;

    return Response.json({
      reply,
      memory:
        updatedMemory,
      misakiTodayMemory:
        updatedTodayMemory,
      relationshipPoints:
        safeRelationshipPoints,
      usage: {
        messageCount:
          typeof usage.message_count ===
          "number"
            ? usage.message_count
            : 0,
        remaining:
          typeof usage.remaining ===
          "number"
            ? usage.remaining
            : 0,
        isPremium:
          usage.is_premium ===
          true,
      },
    });
  } catch (error) {
    console.error(
      "CHAT ROUTE ERROR:",
      error
    );

    const refunded =
      await refundIfCharged();

    return Response.json(
      {
        error:
          "今ちょっと美咲とつながりにくいみたい。少ししてからもう一度話しかけてね。",
        ...(refunded
          ? {
              usage: {
                messageCount:
                  refunded.message_count ?? 0,
                remaining:
                  refunded.remaining ?? 0,
                isPremium:
                  refunded.is_premium === true,
              },
            }
          : {}),
      },
      {
        status: 500,
      }
    );
  }
}

