source.text:
"use client";

import {
  useEffect,
  useState,
} from "react";

import {
  supabase,
} from "../../lib/supabase";

import {
  registerPushSubscription,
  sendTestPushNotification,
} from "../../lib/push-notifications";

type ChatMessage = {
  role: "misaki" | "user";
  text: string;
};

type DailyUsage = {
  date: string;
  count: number;
};

type MisakiTodayMemory = {
  date: string;
  items: string[];
};

type Plan =
  | "free"
  | "premium";

type UsageRpcResult = {
  message_count?: number;
  remaining?: number;
  is_premium?: boolean;
};

type ApiUsage = {
  messageCount?: number;
  remaining?: number;
  isPremium?: boolean;
};

const STORAGE_KEY =
  "misaki-chat-history";

const MEMORY_KEY =
  "misaki-long-term-memory";

const PROACTIVE_KEY =
  "misaki-proactive-state";

const RELATIONSHIP_KEY =
  "misaki-relationship-points";

const MISAKI_TODAY_MEMORY_KEY =
  "misaki-today-memory";

const MAX_MESSAGES = 60;

// 無料版は1日20往復まで
const FREE_DAILY_LIMIT = 20;

// 5分ごとに、自発メッセージの予定時刻になったか確認
const PROACTIVE_CHECK_MS =
  5 * 60 * 1000;

// 自発メッセージ同士は最低45分空ける
const PROACTIVE_COOLDOWN_MS =
  45 * 60 * 1000;

// 次の自発メッセージは45分〜3時間30分の間でランダム
const PROACTIVE_MIN_DELAY_MS =
  45 * 60 * 1000;

const PROACTIVE_MAX_DELAY_MS =
  3.5 * 60 * 60 * 1000;

// 1日最大4回
const MAX_PROACTIVE_PER_DAY =
  4;

const INITIAL_MESSAGES:
  ChatMessage[] = [];

function getRandomProactiveDelayMs() {
  return Math.floor(
    PROACTIVE_MIN_DELAY_MS +
      Math.random() *
        (
          PROACTIVE_MAX_DELAY_MS -
          PROACTIVE_MIN_DELAY_MS
        )
  );
}

function getJapanDateKey() {
  return new Date()
    .toLocaleDateString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",
      }
    );
}

function getJapanCurrentTime() {
  return new Date()
    .toLocaleString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",

        weekday:
          "short",

        hour:
          "2-digit",

        minute:
          "2-digit",

        hour12:
          false,
      }
    );
}

function createEmptyTodayMemory():
  MisakiTodayMemory {
  return {
    date:
      getJapanDateKey(),

    items: [],
  };
}

function isPremiumActive(
  plan:
    | string
    | null
    | undefined,

  premiumUntil:
    | string
    | null
    | undefined
) {
  if (
    plan !==
    "premium"
  ) {
    return false;
  }

  if (
    !premiumUntil
  ) {
    return true;
  }

  const expiresAt =
    new Date(
      premiumUntil
    ).getTime();

  if (
    !Number.isFinite(
      expiresAt
    )
  ) {
    return false;
  }

  return (
    expiresAt >
    Date.now()
  );
}

function getFirstRpcRow<T>(
  value: unknown
): T | null {
  if (
    Array.isArray(
      value
    ) &&
    value.length >
      0
  ) {
    return value[0] as T;
  }

  if (
    value &&
    typeof value ===
      "object"
  ) {
    return value as T;
  }

  return null;
}

export default function ChatPage() {
  const [
    message,
    setMessage,
  ] =
    useState("");

  const [
    messages,
    setMessages,
  ] =
    useState<
      ChatMessage[]
    >(
      INITIAL_MESSAGES
    );

  const [
    memory,
    setMemory,
  ] =
    useState<
      string[]
    >([]);

  const [
    misakiTodayMemory,
    setMisakiTodayMemory,
  ] =
    useState<
      MisakiTodayMemory
    >(
      createEmptyTodayMemory()
    );

  const [
    relationshipPoints,
    setRelationshipPoints,
  ] =
    useState(0);

  const [
    dailyUsage,
    setDailyUsage,
  ] =
    useState<
      DailyUsage
    >({
      date:
        getJapanDateKey(),

      count:
        0,
    });

  const [
    plan,
    setPlan,
  ] =
    useState<
      Plan
    >(
      "free"
    );

  const [
    accountLoaded,
    setAccountLoaded,
  ] =
    useState(
      false
    );

  const [
    showPremium,
    setShowPremium,
  ] =
    useState(
      false
    );

  const [
    showMemory,
    setShowMemory,
  ] =
    useState(
      false
    );

  const [
    showMenu,
    setShowMenu,
  ] =
    useState(
      false
    );

  const [
    loading,
    setLoading,
  ] =
    useState(
      false
    );

  const [
    sendError,
    setSendError,
  ] =
    useState(
      ""
    );

  const [
    loaded,
    setLoaded,
  ] =
    useState(
      false
    );

  const [
    notificationPermission,
    setNotificationPermission,
  ] =
    useState<
      | "default"
      | "granted"
      | "denied"
      | "unsupported"
    >(
      "default"
    );

  const isPremium =
    plan ===
    "premium";

  const today =
    getJapanDateKey();

  const usageCountToday =
    dailyUsage.date ===
    today
      ? dailyUsage.count
      : 0;

  const freeRemaining =
    Math.max(
      0,
      FREE_DAILY_LIMIT -
        usageCountToday
    );

  const freeLimitReached =
    accountLoaded &&
    !isPremium &&
    usageCountToday >=
      FREE_DAILY_LIMIT;

  useEffect(
    () => {
      let active =
        true;

      async function loadEntitlement(
        userId:
          string
      ) {
        for (
          let attempt =
            0;
          attempt <
            5;
          attempt +=
            1
        ) {
          const {
            data,
            error,
          } =
            await supabase
              .from(
                "user_entitlements"
              )
              .select(
                "plan,premium_until"
              )
              .eq(
                "user_id",
                userId
              )
              .maybeSingle();

          if (
            error
          ) {
            throw error;
          }

          if (
            data
          ) {
            return isPremiumActive(
              data.plan,
              data.premium_until
            );
          }

          await new Promise(
            (
              resolve
            ) =>
              window.setTimeout(
                resolve,
                350
              )
          );
        }

        return false;
      }

      async function loadDailyUsage() {
        const {
          data,
          error,
        } =
          await supabase.rpc(
            "get_daily_message_usage"
          );

        if (
          error
        ) {
          throw error;
        }

        const usage =
          getFirstRpcRow<
            UsageRpcResult
          >(
            data
          );

        return {
          count:
            typeof usage
              ?.message_count ===
              "number"
              ? Math.max(
                  0,
                  Math.floor(
                    usage
                      .message_count
                  )
                )
              : 0,

          isPremium:
            usage
              ?.is_premium ===
            true,
        };
      }

      async function initializeAccount() {
        try {
          const {
            data:
              sessionData,
            error:
              sessionError,
          } =
            await supabase
              .auth
              .getSession();

          if (
            sessionError
          ) {
            throw sessionError;
          }

          let user =
            sessionData
              .session
              ?.user ??
            null;

          if (
            !user
          ) {
            const {
              data:
                signInData,
              error:
                signInError,
            } =
              await supabase
                .auth
                .signInAnonymously();

            if (
              signInError
            ) {
              throw signInError;
            }

            user =
              signInData
                .user ??
              null;
          }

          if (
            !user
          ) {
            throw new Error(
              "Supabase user was not created."
            );
          }

          const [
            entitlementPremium,
            usage,
          ] =
            await Promise
              .all([
                loadEntitlement(
                  user.id
                ),

                loadDailyUsage(),
              ]);

          if (
            !active
          ) {
            return;
          }

          const premium =
            entitlementPremium ||
            usage
              .isPremium;

          setPlan(
            premium
              ? "premium"
              : "free"
          );

          setDailyUsage({
            date:
              getJapanDateKey(),

            count:
              usage.count,
          });
        } catch (
          error
        ) {
          console.error(
            "Supabase account initialization failed:",
            error
          );

          if (
            active
          ) {
            setPlan(
              "free"
            );

            setDailyUsage({
              date:
                getJapanDateKey(),

              count:
                0,
            });
          }
        } finally {
          if (
            active
          ) {
            setAccountLoaded(
              true
            );
          }
        }
      }

      initializeAccount();

      return () => {
        active =
          false;
      };
    },
    []
  );

  useEffect(
    () => {
      if (
        !accountLoaded
      ) {
        return;
      }

      if (
        isPremium
      ) {
        setShowPremium(
          false
        );

        return;
      }

      if (
        usageCountToday >=
        FREE_DAILY_LIMIT
      ) {
        setShowPremium(
          true
        );
      }
    },
    [
      accountLoaded,
      isPremium,
      usageCountToday,
    ]
  );

  useEffect(
    () => {
      if (
        "serviceWorker" in
        navigator
      ) {
        navigator
          .serviceWorker
          .register(
            "/sw.js"
          )
          .then(
            (
              registration
            ) => {
              console.log(
                "Service Worker registered:",
                registration
              );
            }
          )
          .catch(
            (
              error
            ) => {
              console.error(
                "Service Worker registration failed:",
                error
              );
            }
          );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !(
          "Notification" in
          window
        )
      ) {
        setNotificationPermission(
          "unsupported"
        );

        return;
      }

      setNotificationPermission(
        Notification
          .permission
      );
    },
    []
  );

  useEffect(
    () => {
      try {
        const savedMessages =
          localStorage
            .getItem(
              STORAGE_KEY
            );

        const savedMemory =
          localStorage
            .getItem(
              MEMORY_KEY
            );

        const savedRelationship =
          localStorage
            .getItem(
              RELATIONSHIP_KEY
            );

        const savedTodayMemory =
          localStorage
            .getItem(
              MISAKI_TODAY_MEMORY_KEY
            );

        let parsedMessages:
          | ChatMessage[]
          | null =
          null;

        if (
          savedMessages
        ) {
          const parsed =
            JSON.parse(
              savedMessages
            );

          if (
            Array.isArray(
              parsed
            )
          ) {
            parsedMessages =
              parsed
                .filter(
                  (
                    item
                  ) =>
                    item &&
                    (
                      item
                        .role ===
                        "user" ||
                      item
                        .role ===
                        "misaki"
                    ) &&
                    typeof item
                      .text ===
                      "string"
                )
                .slice(
                  -MAX_MESSAGES
                );

            setMessages(
              parsedMessages
            );
          }
        }

        if (
          savedMemory
        ) {
          const parsedMemory =
            JSON.parse(
              savedMemory
            );

          if (
            Array.isArray(
              parsedMemory
            )
          ) {
            setMemory(
              parsedMemory
                .filter(
                  (
                    item
                  ) =>
                    typeof item ===
                    "string"
                )
            );
          }
        }

        if (
          savedRelationship
        ) {
          const parsedPoints =
            Number(
              savedRelationship
            );

          if (
            Number
              .isFinite(
                parsedPoints
              ) &&
            parsedPoints >=
              0
          ) {
            setRelationshipPoints(
              Math.floor(
                parsedPoints
              )
            );
          }
        } else if (
          parsedMessages
        ) {
          const previousUserMessages =
            parsedMessages
              .filter(
                (
                  item
                ) =>
                  item.role ===
                  "user"
              )
              .length;

          setRelationshipPoints(
            previousUserMessages
          );
        }

        const currentDate =
          getJapanDateKey();

        if (
          savedTodayMemory
        ) {
          const parsedTodayMemory =
            JSON.parse(
              savedTodayMemory
            );

          if (
            parsedTodayMemory &&
            parsedTodayMemory
              .date ===
              currentDate &&
            Array.isArray(
              parsedTodayMemory
                .items
            )
          ) {
            setMisakiTodayMemory({
              date:
                currentDate,

              items:
                parsedTodayMemory
                  .items
                  .filter(
                    (
                      item:
                        unknown
                    ) =>
                      typeof item ===
                        "string" &&
                      item
                        .trim()
                        .length >
                        0
                  )
                  .map(
                    (
                      item:
                        string
                    ) =>
                      item
                        .trim()
                  )
                  .slice(
                    -12
                  ),
            });
          } else {
            setMisakiTodayMemory({
              date:
                currentDate,

              items:
                [],
            });
          }
        } else {
          setMisakiTodayMemory({
            date:
              currentDate,

            items:
              [],
          });
        }
      } catch (
        error
      ) {
        console.error(
          "Failed to load saved data:",
          error
        );

        const currentDate =
          getJapanDateKey();

        setMisakiTodayMemory({
          date:
            currentDate,

          items:
            [],
        });
      } finally {
        setLoaded(
          true
        );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const limitedMessages =
          messages
            .slice(
              -MAX_MESSAGES
            );

        localStorage
          .setItem(
            STORAGE_KEY,

            JSON.stringify(
              limitedMessages
            )
