  async function getAccessToken() {
    const {
      data,
      error,
    } =
      await supabase
        .auth
        .getSession();

    if (
      error
    ) {
      throw error;
    }

    const accessToken =
      data
        .session
        ?.access_token;

    if (
      !accessToken
    ) {
      throw new Error(
        "ログイン情報を確認できませんでした。ページを再読み込みしてね。"
      );
    }

    return accessToken;
  }

  function applyApiUsage(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const usage =
      value as
        ApiUsage;

    if (
      usage
        .isPremium ===
      true
    ) {
      setPlan(
        "premium"
      );
    }

    if (
      typeof usage
        .messageCount ===
        "number" &&
      Number.isFinite(
        usage
          .messageCount
      )
    ) {
      setDailyUsage({
        date:
          getJapanDateKey(),

        count:
          Math.max(
            0,

            Math.floor(
              usage
                .messageCount
            )
          ),
      });
    }
  }

  async function requestNotificationPermission() {
    if (
      !(
        "Notification" in
        window
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "serviceWorker" in
        navigator
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "PushManager" in
        window
      )
    ) {
      alert(
        "このブラウザはPush通知に対応していません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    try {
      await navigator
        .serviceWorker
        .ready;

      const permission =
        await Notification
          .requestPermission();

      setNotificationPermission(
        permission
      );

      if (
        permission ===
        "denied"
      ) {
        alert(
          "通知が許可されませんでした。端末の設定から美咲の通知を許可してください。"
        );

        return;
      }

      if (
        permission !==
        "granted"
      ) {
        return;
      }

      await registerPushSubscription();

      const accessToken =
        await getAccessToken();

      try {
        await sendTestPushNotification(
          accessToken
        );

        alert(
          "通知をONにしました。今、美咲からテスト通知を送ったよ。"
        );
      } catch (
        testError
      ) {
        console.error(
          "Test push notification failed:",
          testError
        );

        alert(
          "通知端末の登録はできました。テスト通知だけ送信できませんでした。"
        );
      }
    } catch (
      error
    ) {
      console.error(
        "Push notification setup error:",
        error
      );

      const errorMessage =
        error instanceof
        Error
          ? error.message
          : "通知の設定に失敗しました。";

      alert(
        errorMessage
      );
    }
  }

