  function applyTodayMemory(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const data =
      value as {
        date?:
          unknown;

        items?:
          unknown;
      };

    const currentDate =
      getJapanDateKey();

    if (
      data.date !==
        currentDate ||
      !Array.isArray(
        data.items
      )
    ) {
      return;
    }

    const items =
      data
        .items
        .filter(
          (
            item:
              unknown
          ) =>
            typeof item ===
              "string" &&
            item
              .trim()
              .length >
              0
        )
        .map(
          (
            item
          ) =>
            (
              item as string
            )
              .trim()
        )
        .slice(
          -12
        );

    setMisakiTodayMemory({
      date:
        currentDate,

      items:
        Array.from(
          new Set(
            items
          )
        ),
    });
  }

  async function sendMessage() {
    const text =
      message
        .trim();

    if (
      !text ||
      loading ||
      !accountLoaded
    ) {
      return;
    }

    const currentDate =
      getJapanDateKey();

    if (
      !isPremium &&
      usageCountToday >=
        FREE_DAILY_LIMIT
    ) {
      setShowPremium(
        true
      );

      return;
    }

    setLoading(
      true
    );

    setSendError(
      ""
    );

    try {
      const accessToken =
        await getAccessToken();

      const userMessage:
        ChatMessage = {
          role:
            "user",

          text,
        };

      const newMessages =
        [
          ...messages,
          userMessage,
        ]
          .slice(
            -MAX_MESSAGES
          );

      setMessages(
        newMessages
      );

      setMessage(
        ""
      );

      const nextRelationshipPoints =
        relationshipPoints +
        1;

      const currentTime =
        getJapanCurrentTime();

      const todayMemoryForRequest =
        misakiTodayMemory
          .date ===
          currentDate
          ? misakiTodayMemory
          : {
              date:
                currentDate,

              items:
                [],
            };

      const res =
        await fetch(
          "/api/chat",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/json",

              Authorization:
                `Bearer ${accessToken}`,
            },

            body:
              JSON.stringify({
                message:
                  text,

                history:
                  messages
                    .slice(
                      -MAX_MESSAGES
                    ),

                memory,

                misakiTodayMemory:
                  todayMemoryForRequest,

                currentTime,

                relationshipPoints:
                  nextRelationshipPoints,
              }),
          }
        );

      const data =
        await res
          .json();

      applyApiUsage(
        data?.usage
      );

      if (
        res.status ===
        429
      ) {
        setShowPremium(
          true
        );

        setMessages(
          (
            prev
          ) =>
            prev
              .filter(
                (
                  item,
                  index
                ) =>
                  !(
                    index ===
                      prev.length -
                        1 &&
                    item.role ===
                      "user" &&
                    item.text ===
                      text
                  )
              )
        );

        return;
      }

      if (
        !res.ok
      ) {
        throw new Error(
          data?.error ||
            "通信に失敗しました"
        );
      }

      if (
        Array.isArray(
          data.memory
        )
      ) {
        setMemory(
          data.memory
            .filter(
              (
                item:
                  unknown
              ) =>
                typeof item ===
                "string"
            )
        );
      }

      applyTodayMemory(
        data
          .misakiTodayMemory
      );

      setRelationshipPoints(
        nextRelationshipPoints
      );

      setMessages(
        (
          prev
        ) =>
          [
            ...prev,

            {
              role:
                "misaki" as const,

              text:
                data.reply ||
                "返事を取得できませんでした。",
            },
          ]
            .slice(
              -MAX_MESSAGES
            )
      );
    } catch (
      error:
        any
    ) {
      console.error(
        "Chat message error:",
        error
      );

      setSendError(
        error instanceof Error &&
        error.message
          ? error.message
          : "返事を受け取れませんでした。もう一度送ってみてね。"
      );
    } finally {
      setLoading(
        false
      );
    }
  }

  async function sendProactiveMessage() {
    if (
      loading ||
      !loaded ||
      !accountLoaded
    ) {
      return;
    }

    if (
      document
        .visibilityState !==
      "visible"
    ) {
      return;
    }

    if (
      message
        .trim()
        .length >
      0
    ) {
      return;
    }

    const now =
      Date.now();

    const currentDate =
      getJapanDateKey();

    let state = {
      date:
        currentDate,

      count:
        0,

      lastSentAt:
        0,

      nextAttemptAt:
        0,
    };

    try {
      const saved =
        localStorage
          .getItem(
            PROACTIVE_KEY
          );

      if (
        saved
      ) {
        const parsed =
          JSON.parse(
            saved
          );

        if (
          parsed &&
          parsed.date ===
            currentDate
        ) {
          state = {
            date:
              currentDate,

            count:
              typeof parsed
                .count ===
                "number"
                ? parsed.count
                : 0,

            lastSentAt:
              typeof parsed
                .lastSentAt ===
                "number"
                ? parsed
                    .lastSentAt
                : 0,

            nextAttemptAt:
              typeof parsed
                .nextAttemptAt ===
                "number"
                ? parsed
                    .nextAttemptAt
                : 0,
          };
        }
      }
    } catch (
      error
    ) {
      console.error(
        "Failed to load proactive state:",
        error
      );
    }

    if (
      state.count >=
      MAX_PROACTIVE_PER_DAY
    ) {
      return;
    }

    if (
      state.lastSentAt >
        0 &&
      now -
        state.lastSentAt <
        PROACTIVE_COOLDOWN_MS
    ) {
      return;
    }

    if (
      state.nextAttemptAt <=
      0
    ) {
      const nextAttemptAt =
        now +
        getRandomProactiveDelayMs();

      localStorage
        .setItem(
          PROACTIVE_KEY,

          JSON.stringify({
            ...state,

            nextAttemptAt,
          })
        );

      return;
    }

    if (
      now <
      state.nextAttemptAt
    ) {
      return;
    }

    try {
      const accessToken =
        await getAccessToken();

      const currentTime =
        getJapanCurrentTime();

      const todayMemoryForRequest =
        misakiTodayMemory
          .date ===
          currentDate
          ? misakiTodayMemory
          : {
              date:
                currentDate,

              items:
                [],
            };

      const res =
        await fetch(
          "/api/proactive",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/json",

              Authorization:
                `Bearer ${accessToken}`,
            },

            body:
              JSON.stringify({
                history:
                  messages
                    .slice(
                      -MAX_MESSAGES
                    ),

                memory,

                misakiTodayMemory:
                  todayMemoryForRequest,

                currentTime,

                relationshipPoints,
              }),
          }
        );

      const data =
        await res
          .json();

      if (
        !res.ok
      ) {
        console.error(
          "Proactive message failed:",
          data
        );

        return;
      }

      if (
        data.sent ===
        false
      ) {
        return;
      }

      if (
        !data.reply ||
        typeof data
          .reply !==
          "string"
      ) {
        return;
      }

      if (
        Array.isArray(
          data.memory
        )
      ) {
        setMemory(
          data.memory
            .filter(
              (
                item:
                  unknown
              ) =>
                typeof item ===
                "string"
            )
        );
      }

      applyTodayMemory(
        data
          .misakiTodayMemory
      );

      setMessages(
        (
          prev
        ) =>
          [
            ...prev,

            {
              role:
                "misaki" as const,

              text:
                data.reply,
            },
          ]
            .slice(
              -MAX_MESSAGES
            )
      );

      const nextState = {
        date:
          currentDate,

        count:
          state.count +
          1,

        lastSentAt:
          now,

        nextAttemptAt:
          now +
          getRandomProactiveDelayMs(),
      };

      localStorage
        .setItem(
          PROACTIVE_KEY,

          JSON.stringify(
            nextState
          )
        );
    } catch (
      error
    ) {
      console.error(
        "Proactive message error:",
        error
      );
    }
  }

