            </p>

            {freeLimitReached && (
              <div
                className="premiumLimitMessage"
              >
                今日は無料分の20回まで話したよ。
              </div>
            )}

            <button
              className="premiumButton"
              onClick={
                startPremium
              }
            >
              プレミアムを始める
            </button>

            <p
              className="premiumNote"
            >
              現在はテスト中のため、
              まだ料金は発生しません。
            </p>
          </section>
        )}

      {/* =========================
          CHAT
      ========================== */}

      <section
        className="chat"
      >
        {messages.length ===
          0 &&
          !loading && (
            <div
              className="emptyConversation"
            >
              <img
                src="/icon-192.png"
                alt=""
              />

              <p>
                なんでもない話でいいよ。
              </p>

              <span>
                Misaki
              </span>
            </div>
          )}

        {messages.map(
          (
            item,
            index
          ) => (
            <div
              key={
                index
              }
              className={`bubble ${
                item.role ===
                "user"
                  ? "user"
                  : ""
              }`}
            >
              {item.text}
            </div>
          )
        )}

        {loading && (
          <div
            className="bubble typingBubble"
          >
